@@ -0,0 +1,15 @@
+import fs from "node:fs";
+const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
+const deps = { ...pkg.dependencies, ...pkg.devDependencies };
+const src = fs
+  .readFileSync("src/services/gemini.js", "utf8")
+  .split("\n")
+  .filter((l) => !l.trim().startsWith("//"))
+  .join("\n");
+const errs = [];
+if (deps["@google/generative-ai"]) errs.push("old package still listed");
+if (!deps["@google/genai"]) errs.push("new package missing");
+if (/generative-ai|getGenerativeModel|GoogleGenerativeAI/.test(src)) errs.push("old API in source");
+if (!/models\.generateContent\(/.test(src)) errs.push("no models.generateContent call");
+if (errs.length) { console.error(errs.join("\n")); process.exit(1); }
+console.log("ok");
