+import fs from "node:fs";
+const src = fs.readFileSync("src/services/gemini.js", "utf8");
+const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
+const code = src.split("\n").filter((l) => !l.trim().startsWith("//")).join("\n");
+const fails = [];
+if (pkg.dependencies?.["@google/generative-ai"]) fails.push("old sdk still listed");
+if (!pkg.dependencies?.["@google/genai"]) fails.push("new sdk missing");
+if (/generative-ai|getGenerativeModel/.test(code)) fails.push("legacy API used");
+if (!/models\.generateContent\(/.test(code)) fails.push("no models.generateContent");
+if (!/store:\s*false/.test(code)) fails.push("store:false missing");
+if (fails.length) { console.error(fails.join("\n")); process.exit(1); }
+console.log("ok");
